package com.example

/**
 * Curated, 100% syllabus-aligned, distinct Flashcards for Sinhala (සිංහල භාෂාව හා සාහිත්‍යය).
 * Part 1: Categories 1 to 10 (20 distinct questions per category).
 * Strictly guarantees no repeated questions within the same category or across different categories.
 */
object FlashcardBankSinhalaSets {

  fun getCard(setNum: Int, cardNum: Int, grade: String): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      1 -> when(grade) {
        "10" -> set1_Grade10[(c-1)%set1_Grade10.size]
        "11" -> set1_Grade11[(c-1)%set1_Grade11.size]
        else -> set1_Grade9[(c-1)%set1_Grade9.size]
      }
      2 -> when(grade) {
        "10" -> set2_Grade10[(c-1)%set2_Grade10.size]
        "11" -> set2_Grade11[(c-1)%set2_Grade11.size]
        else -> set2[(c-1)%set2.size]
      }
      3 -> when(grade) {
        "10" -> set3_Grade10[(c-1)%set3_Grade10.size]
        "11" -> set3_Grade11[(c-1)%set3_Grade11.size]
        else -> set3[(c-1)%set3.size]
      }
      4 -> when(grade) {
        "10" -> set4_Grade10[(c-1)%set4_Grade10.size]
        "11" -> set4_Grade11[(c-1)%set4_Grade11.size]
        else -> set4[(c-1)%set4.size]
      }
      5 -> set5[(c - 1) % set5.size]
      6 -> set6[(c - 1) % set6.size]
      7 -> set7[(c - 1) % set7.size]
      8 -> set8[(c - 1) % set8.size]
      9 -> set9[(c - 1) % set9.size]
      10 -> set10[(c - 1) % set10.size]
      else -> FlashcardBankSinhalaSetsPart2.getCard(setNum, cardNum, grade)
    }
  }

  // --- SET 1: සිංහල හෝඩිය, ස්වර/ව්‍යඤ්ජන & ශබ්ද විද්‍යාව ---
  private val set1_Grade9 = listOf(
    CardContentTuple("ශුද්ධ සිංහල හෝඩියේ (අමිශ්‍ර හෝඩිය) අක්ෂර ගණන කීයද?", "අක්ෂර 32 කි. ස්වර 12ක් සහ ව්‍යඤ්ජන 20ක් අයත් වේ.", "සිදත් සඟරාවේ දක්වා ඇත්තේ මෙම හෝඩියයි.", "අක්ෂර 32 (ස්වර 12, ව්‍යඤ්ජන 20)"),
    CardContentTuple("මිශ්‍ර සිංහල හෝඩියේ සමස්ත අක්ෂර ගණන කීයද?", "අක්ෂර 54 කි. ස්වර 18ක් සහ ව්‍යඤ්ජන 36ක් අයත් වේ.", "සංස්කෘත සහ පාලි තත්සම වචන ලිවීමට යොදාගනී.", "අක්ෂර 54 (ස්වර 18, ව්‍යඤ්ජන 36)"),
    CardContentTuple("ජාතික අධ්‍යාපන ආයතනය සම්මත කළ නූතන සිංහල හෝඩියේ අක්ෂර ගණන කීයද?", "අක්ෂර 60 කි. 'ඇ', 'ඈ' සහ ඉංග්‍රීසි 'f' ශබ්දය සඳහා 'ෆ' අකුරද ඇතුළත් වේ.", "නූතන ශබ්ද විද්‍යාත්මක හෝඩියයි.", "අක්ෂර 60"),
    CardContentTuple("හ්‍රස්ව ස්වර සහ දීර්ඝ ස්වර අතර වෙනස කුමක්ද?", "හ්‍රස්ව ස්වර = එක් මාත්‍රාවකින් උච්චාරණය වන කෙටි ස්වර (අ, ඉ, උ, එ, ඔ, ඇ).\nදීර්ඝ ස්වර = මාත්‍රා දෙකකින් උච්චාරණය වන දිගු ස්වර (ආ, ඊ, ඌ, ඒ, ඕ, ඈ).", "මාත්‍රා කාලය අනුව වෙනස් වේ.", "හ්‍රස්ව (1 මාත්‍රා) vs දීර්ඝ (2 මාත්‍රා)"),
    CardContentTuple("සිංහල හෝඩියේ ඇති සංවෘත 'ඇ' සහ විවෘත 'ඇ' යනු කුමක්ද?", "තල්ල දෙසට දිව ඔසවා තොල් විවර කර උච්චාරණය වන විශේෂ ස්වර දෙකයි. හෙළ බසටම අනන්‍ය වූවකි.", "කැත්ත (හ්‍රස්ව), කෑවා (දීර්ඝ).", "ඇ / ඈ ස්වර"),
    CardContentTuple("ඝෝෂ (නාද) සහ අඝෝෂ (අනාද) අක්ෂර යනු මොනවාද?", "ඝෝෂ = උගුරේ කටහඬ තන්තු කම්පනය වී පිටවන අකුරු (ග, ඝ, ජ, ඣ, ඩ, ඪ, ද, ධ, බ, භ).\nඅඝෝෂ = කටහඬ තන්තු කම්පනය නොවී පිටවන අකුරු (ක, ඛ, ච, ඡ, ට, ඨ, ත, ථ, ප, ඵ).", "වර්ගයේ 1, 2 අඝෝෂ වන අතර 3, 4 ඝෝෂ වේ.", "අඝෝෂ vs ඝෝෂ"),
